    let myCookie = java.getCookie($$$['url']);
    let ua = java.getWebViewUA();
    let header = {
	"Content-Type": "application/x-www-form-urlencoded", 
	"Accept": "application/json, text/plain, */*",
	"User-Agent": ua,
	"cookie": myCookie
   };
    code = java.getVerificationCode($$$['url'] + '/captcha');
    let data = 'checkCode=' + code;
